-- R4 Unified Access Management Backend.
-- Adds one canonical administration facade without creating a second IAM/RBAC domain.

select set_config('app.current_tenant_id','INSTANCE',true);
select set_config('app.current_actor_id','r4-unified-access-management',true);

comment on column departments.manager_user_id is
'Official Department Manager organizational relationship. It is not a User attribute, Department membership type, or RBAC Role.';

comment on table org_tenant_memberships is
'Tenant admission boundary only. Administrative authority is granted exclusively through RBAC Role Bindings.';

comment on table org_department_memberships is
'Department placement and Primary Department relationship only. MEMBER and DELEGATE never imply an Access Role.';

comment on table org_group_memberships is
'Group membership relationship only. Access is inherited only when the Group principal has an active RBAC Role Binding.';

