on conflict(entry_point_id) do update set
 entry_point_type=excluded.entry_point_type,application_id=excluded.application_id,owner_module=excluded.owner_module,
 display_name=excluded.display_name,route_pattern=excluded.route_pattern,http_method=excluded.http_method,
 authority_state='TARGET_ONLY',target_permission_code=excluded.target_permission_code,legacy_authority_type=null,
 legacy_authorities='[]'::jsonb,resource_type=excluded.resource_type,resource_resolver_id=excluded.resource_resolver_id,
 exemption_reason=null,migration_deadline=null,manifest_revision=excluded.manifest_revision,source_ref=excluded.source_ref,
 source_hash=excluded.source_hash,last_verified_at=now(),updated_at=now(),updated_by='r4-unified-access-management',
 version=permission_entry_point_inventory.version+1;

do $$
declare route_count integer;
begin
 select count(*) into route_count from permission_entry_point_inventory
  where manifest_revision='r4-unified-access-management-2026-08-03' and authority_state='TARGET_ONLY';
 if route_count <> 58 then
   raise exception 'R4 unified access route inventory incomplete: expected 58, found %',route_count;
 end if;
 if exists(select 1 from permission_entry_point_inventory
   where manifest_revision='r4-unified-access-management-2026-08-03'
     and (target_permission_code is null or resource_resolver_id is null or authority_state<>'TARGET_ONLY')) then
   raise exception 'R4 unified access route has incomplete canonical authorization metadata';
 end if;
 if exists(select 1 from org_department_memberships where membership_type='MANAGER') then
   raise exception 'R4 Manager semantics violation: MANAGER remains a Department membership type';
 end if;
end $$;

update rbac_policy_versions set policy_version=policy_version+1,updated_at=now(),updated_by='r4-unified-access-management';
insert into rbac_policy_versions(scope_type,scope_id,tenant_id,policy_version,updated_at,updated_by)
select 'TENANT',tenant_id,tenant_id,1,now(),'r4-unified-access-management' from tenants
on conflict(scope_type,scope_id) do update set policy_version=rbac_policy_versions.policy_version+1,updated_at=now(),updated_by='r4-unified-access-management';
